package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.base.SailDataset;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Collecting a quoted triple term cascades to its components. A component whose own statements were removed later must
 * still wait for the readers that see those statements.
 */
class LmdbRetiredValueCascadeTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI A = VF.createIRI("urn:cascade:a");
	private static final IRI P = VF.createIRI("urn:cascade:p");
	private static final IRI B = VF.createIRI("urn:cascade:b");
	private static final IRI SOURCE = VF.createIRI("urn:cascade:source");
	private static final IRI X = VF.createIRI("urn:cascade:x");
	private static final IRI Q = VF.createIRI("urn:cascade:q");
	private static final IRI C = VF.createIRI("urn:cascade:c");

	@Test
	void aComponentRemovedAfterItsQuotingTermWaitsForReadersBetweenTheTwoRemovals(@TempDir File dataDir)
			throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc"));
		store.init();
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			TripleTerm term = VF.createTripleTerm(A, P, B);
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(X, SOURCE, term);
				writer.addStatement(A, Q, C);
				writer.commit();
			}
			long componentId = values.getId(A);
			assertNotEquals(LmdbValue.UNKNOWN_ID, componentId);

			SailDataset beforeBoth = pin(store, A, Q, C);
			remove(store, X, SOURCE, term);
			SailDataset betweenRemovals = pin(store, A, Q, C);
			try {
				remove(store, A, Q, C);
				// The term may now go; its component may not, because betweenRemovals still sees (a q c).
				beforeBoth.close();
				for (int round = 0; round < 4; round++) {
					store.getBackingStore().completePostCommitValueMaintenance();
				}
				try (CloseableIteration<? extends Statement> statements = betweenRemovals.getStatements(A, Q, C)) {
					assertTrue(statements.hasNext(), "the pinned reader still sees the later removal's statement");
				}
				assertEquals(componentId, values.getId(A),
						"a value visible to an open reader keeps its dictionary entry until that reader closes");
			} finally {
				betweenRemovals.close();
			}
		} finally {
			store.shutDown();
		}
	}

	private static SailDataset pin(LmdbStore store, Resource subject, IRI predicate, Value object) {
		SailDataset dataset = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
		try (CloseableIteration<? extends Statement> statements = dataset.getStatements(subject, predicate, object)) {
			assertTrue(statements.hasNext());
		}
		return dataset;
	}

	private static void remove(LmdbStore store, Resource subject, IRI predicate, Value object) {
		try (SailConnection writer = store.getConnection()) {
			writer.begin(IsolationLevels.SNAPSHOT);
			writer.removeStatements(subject, predicate, object);
			writer.commit();
		}
	}
}
